import{_ as t,o as r,c as i,a2 as l}from"./chunks/framework.CHeM0PsO.js";const f=JSON.parse('{"title":"2022 总结 - bennyhuo","description":null,"frontmatter":{"title":"2022 总结 - bennyhuo","keywords":"2022 总结","date":"2022/12/31 07:12:13","description":null,"tags":[2022],"permalink":"/2022/12/31/summary-2022/"},"headers":[],"relativePath":"posts/summary-2022.md","filePath":"posts/summary-2022.md","lastUpdated":1785284005000}'),o={name:"posts/summary-2022.md"};function a(n,e,p,s,b,h){return r(),i("div",null,[...e[0]||(e[0]=[l('<blockquote><p>也还是闲不住的一年呢。</p></blockquote><p>一年又过去了。这一年也还是做了很多事情的。</p><h2 id="视频内容输出" tabindex="-1">视频内容输出 <a class="header-anchor" href="#视频内容输出" aria-label="Permalink to &quot;视频内容输出&quot;">​</a></h2><p>今年继续在 B 站发视频，欢迎关注：<a href="https://space.bilibili.com/28615855" target="_blank" rel="noreferrer"><strong>bennyhuo 不是算命的</strong></a>。</p><p><img src="https://kotlinblog-1251218094.costj.myqcloud.com/48cc2b74-2ef8-40db-8418-9d9756bfdf14/media/20221228152123.png" alt=""></p><p>相比去年（2021 年），今年的视频大多数是读书视频。</p><ul><li><a href="https://www.bilibili.com/video/BV1Ni4y1U714/" target="_blank" rel="noreferrer">《深入理解 Kotlin 协程》完结 共 16 集</a></li><li><a href="https://www.bilibili.com/video/BV1vv4y1A7fX/" target="_blank" rel="noreferrer">《渡劫 C++ 协程》完结 共 7 集</a></li><li><a href="https://www.bilibili.com/video/BV1UY4y1z7W7/" target="_blank" rel="noreferrer">《TypeScript 入门》完结 共 10 集</a></li><li><a href="https://www.bilibili.com/video/BV1Fu411Q7af/" target="_blank" rel="noreferrer">《Dart 开发语言概览》完结 共 17 集</a></li><li><a href="https://www.bilibili.com/video/BV13T4y1k7qQ/" target="_blank" rel="noreferrer">《现代 C++ 特性解析》更新至第六章，共 11 集</a></li><li><a href="https://www.bilibili.com/video/BV1HB4y1C7zH/" target="_blank" rel="noreferrer">《Effective Python》更新至第 15 条，共 14 集</a></li><li><a href="https://www.bilibili.com/video/BV1NR4y1A7Tk/" target="_blank" rel="noreferrer">《Rust 程序设计语言》更新至第七章，共 23 集</a></li><li><a href="https://www.bilibili.com/video/BV1ZV4y1L7Kx/" target="_blank" rel="noreferrer">《Jetpack Compose 从入门到实战》更新至第二章，共 12 集</a></li></ul><p>Kotlin 版本更新的视频：</p><ul><li><a href="https://www.bilibili.com/video/BV1eM4y1P7cR/" target="_blank" rel="noreferrer">Kotlin 1.6 共 6 期</a></li><li><a href="https://www.bilibili.com/video/BV1ma411E7ZU/" target="_blank" rel="noreferrer">Kotlin 1.7 共 2 期</a></li></ul><p>还有一些散装的视频，比如<a href="https://www.bilibili.com/video/BV1pT4y1Y746/" target="_blank" rel="noreferrer">“神奇的 C 语言”</a>系列，说起来 C 语言的视频播放量是真的高。</p><p>订阅量从年初的 5900 左右增长到接近 17500，基本达到了我年初的预期（12000），<strong>谢谢大家的关注和一键三连</strong>。不瞒各位说，我当时还定了一个挑战目标：18000，还真是恰到好处的差一点儿。</p><p>2023 年的想法，未更新完的读书视频当中，这几本是确定要更完的：</p><ul><li>《Effective Python》</li><li>《Rust 程序设计语言》</li><li>《现代 C++ 特性解析》</li></ul><p>此外应该也会有一些 Java 相关的视频。</p><p>小伙伴们问得最多的是 Flutter 不更了吗，Compose 不更了吗？统一回复：对，不更了。</p><h2 id="文字内容输出" tabindex="-1">文字内容输出 <a class="header-anchor" href="#文字内容输出" aria-label="Permalink to &quot;文字内容输出&quot;">​</a></h2><p>今年文章写得不多，也就两个合集：</p><ul><li><a href="https://www.bennyhuo.com/book/cpp-coroutines/" target="_blank" rel="noreferrer">渡劫 C++ 协程</a></li><li><a href="https://www.bennyhuo.com/book/swift-coroutines/" target="_blank" rel="noreferrer">闲话 Swift 协程</a></li></ul><p>尽管写完《深入理解 Kotlin 协程》之后我就对协程这个话题比较麻木了，不过对于其他语言的协程我还是很好奇的。C++ 和 Swift 的协程的实现与 Kotlin 协程有很多相似之处，有兴趣的朋友不妨读一下这几篇文章了解一下。</p><p>今年也在写书。“深入实践 Kotlin 元编程”（暂定书名）这本书目前底稿已经全部完成，我目前正在逐字逐句做校对，预计还需要一个多月才能全部交付到编辑侧完成第一遍审稿。参考《深入理解 Kotlin 协程》的时间，2023 年内出版是没什么问题的。</p><p>这本书的内容大概涵盖了 Kotlin 开发实践当中另一个难点。大家常听说的 APT、KSP、KCP 在这本书当中都有详细介绍。如果大家想要提前了解书的内容，可以看一下我的 GitHub 2022 年的提交记录。经常有朋友我问有没有好的 KSP 或者 KCP 的示例代码，其实我近一年维护的所有项目基本上都与之相关。</p><p>写书是一件苦差事，每次写书的时候都在心里说写完这本就再也不写了。也许明年可以尝试写一些小册子，搞轻松一些。“渡劫 C++ 协程” 这种我觉得就挺好。</p><h2 id="社区活动" tabindex="-1">社区活动 <a class="header-anchor" href="#社区活动" aria-label="Permalink to &quot;社区活动&quot;">​</a></h2><p>今年的社区活动，一共有三次，其中还包括一次线下活动，真是不容易。</p><ul><li><p><a href="https://www.bilibili.com/video/BV1kG411n7KH/" target="_blank" rel="noreferrer">2022.7 Kotlin 炉边漫谈 Podcast 第二期</a>：“Kotlin 炉边漫谈” 是 Kotlin 社区推出的一款节目，每期都会邀请一些有趣的嘉宾参与闲聊。据说我是那个最不会聊天的。</p></li><li><p><a href="https://www.bilibili.com/video/BV1ye4y1Y728/" target="_blank" rel="noreferrer">2022.9.1 使用 Kotlin 多平台特性统一 JS 调用 Native 函数的体验</a>：这期分享主要介绍了 Klue 这个项目的实现思路和细节。Klue 是 Kotlin 多平台特性的一个很好的实践场景。这个项目明年应该会继续探索下去，今年之所以搁浅，实在是因为精力有限。 <img src="https://kotlinblog-1251218094.costj.myqcloud.com/48cc2b74-2ef8-40db-8418-9d9756bfdf14/media/20221231150245.png" alt=""></p></li><li><p><a href="https://www.bilibili.com/video/BV1t14y1L7SA/" target="_blank" rel="noreferrer">2022.10.30 小猿口算 Android 项目的优化实践</a>：这期分享主要介绍了我在猿辅导公司小猿口算团队与团队其他同学一起做的各方面的工程优化。能把有趣的技术应用到公司项目当中，也是一件快事。 <img src="https://kotlinblog-1251218094.costj.myqcloud.com/48cc2b74-2ef8-40db-8418-9d9756bfdf14/media/20221231152701.png" alt=""></p></li></ul><h2 id="开源项目" tabindex="-1">开源项目 <a class="header-anchor" href="#开源项目" aria-label="Permalink to &quot;开源项目&quot;">​</a></h2><p>2022 年还有一些开源项目在维护。比较重要的就是下面的几个：</p><ul><li><a href="https://github.com/bennyhuo/Kotlin-Trim-Indent" target="_blank" rel="noreferrer">Kotlin-Trim-Indent</a>：处理 Kotlin 多行字符串缩进的编译器插件。</li><li><a href="https://github.com/bennyhuo/KotlinDeepCopy" target="_blank" rel="noreferrer">KotlinDeepCopy</a>：很多年的老项目了，今年又尝试了很多想法。</li><li><a href="https://github.com/bennyhuo/kotlin-compile-testing-extensions" target="_blank" rel="noreferrer">kotlin-compile-testing-extensions</a>：对框架 kotlin-compile-testing 做的扩展，方便做 Kotlin 编译器相关项目的单测。</li><li><a href="https://github.com/bennyhuo/Klue" target="_blank" rel="noreferrer">Klue</a>：使用 Kotlin 多平台特性对 Android/iOS 与 WebView/React Native 的互调用进行简化。</li></ul><p>今年因为写书，一直在做 Kotlin 编译器相关的尝试。明年的重心可能会放到 Klue 上面。</p><h2 id="最后" tabindex="-1">最后 <a class="header-anchor" href="#最后" aria-label="Permalink to &quot;最后&quot;">​</a></h2><p>欢迎大家在 B 站关注我：<strong>bennyhuo 不是算命的</strong>。</p><p>也欢迎大家关注微信公众号：<strong>bennyhuo</strong>。</p><p>2023 继续加油。</p><hr><h2 id="关于作者" tabindex="-1">关于作者 <a class="header-anchor" href="#关于作者" aria-label="Permalink to &quot;关于作者&quot;">​</a></h2><p><strong>霍丙乾 bennyhuo</strong>，Google 开发者专家（Kotlin 方向）；<strong>《深入理解 Kotlin 协程》</strong> 作者（机械工业出版社，2020.6）；<strong>《深入实践 Kotlin 元编程》</strong> 作者（机械工业出版社，2023.8）；移动客户端工程师，先后就职于腾讯地图、猿辅导、腾讯视频。</p><ul><li>GitHub：<a href="https://github.com/bennyhuo" target="_blank" rel="noreferrer">https://github.com/bennyhuo</a></li><li>博客：<a href="https://www.bennyhuo.com" target="_blank" rel="noreferrer">https://www.bennyhuo.com</a></li><li>bilibili：<a href="https://space.bilibili.com/28615855" target="_blank" rel="noreferrer"><strong>霍丙乾 bennyhuo</strong></a></li><li>微信公众号：<strong>霍丙乾 bennyhuo</strong></li></ul>',37)])])}const u=t(o,[["render",a]]);export{f as __pageData,u as default};
